def source_hash_only(obj):
    if isinstance(obj,dict):
        return {k:("APPROVED_DOC_SHA" if k=="sha256" and obj.get("file","").endswith("p49-terminal-batch-design-v1.31-FROZEN.md") else source_hash_only(v)) for k,v in obj.items()}
